def perform_full_commissioning_on_classical_gnb(bts_id=0, scf_path=None, prefix_tag=None, awaiting_time=600,
                                                readiness_timeout=600, custom_config=False, build_directory="/tmp",
                                                remove_build=False, update_timeout=600, force_reconnect=False,
                                                commissioning_timeout=400):
    """
    Perform full commissioning on gNB
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param scf_path: scf_path to gNB - if not set then default will be selected
    :param prefix_tag: scf_path to gNB - if scf_path not passed then default with specific prefix_tag will be selected
    :param awaiting_time: Time in seconds to wait for the Incompatible software alarm to occur
    :param readiness_timeout: Time in seconds to wait for BTS availability
    :param custom_config: Flag for enabling scf collection from custom-config directory
    :param build_directory: path to target directory where build will be downloaded in case of another sw upload need
    :param remove_build: Flag for enabling software package file removing
    :param update_timeout: Time in seconds to wait for BTS SW upload process finishes
    :param force_reconnect: True/False - If True - first disconnect if already connected wiht BTS.
    :param commissioning_timeout: Time in seconds to wait for BTS commissioning process finishes
    """
    _perform_full_commissioning_on_classical_bts(bts_id=bts_id, bts_type="GNB", scf_path=scf_path,
                                                 prefix_tag=prefix_tag,
                                                 awaiting_time=awaiting_time, readiness_timeout=readiness_timeout,
                                                 custom_config=custom_config, build_directory=build_directory,
                                                 remove_build=remove_build, update_timeout=update_timeout,
                                                 force_reconnect=force_reconnect,
                                                 commissioning_timeout=commissioning_timeout)


