def _perform_full_commissioning_on_classical_bts(bts_id=0, bts_type="GNB", scf_path=None, prefix_tag=None,
                                                 awaiting_time=600, readiness_timeout=600, custom_config=False,
                                                 build_directory="/tmp", remove_build=False, update_timeout=600,
                                                 force_reconnect=False, commissioning_timeout=400):
    """
    Perform full commissioning on BTS
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
    :param bts_type: BTS type - eNB or gNB
    :param scf_path: scf_path to gNB - if not set then default will be selected
    :param prefix_tag: scf_path to gNB - if scf_path not passed then default with specific prefix_tag will be selected
    :param awaiting_time: Time in seconds to wait for the Incompatible software alarm to occur
    :param readiness_timeout: Time in seconds to wait for BTS availability
    :param custom_config: Flag for enabling scf collection from custom-config directory
    :param build_directory: path to target directory where build will be downloaded in case of another sw upload need
    :param remove_build: Flag for enabling software package file removing
    :param update_timeout: Time in seconds to wait for BTS SW upload process finishes
    :param force_reconnect: True/False - If True - first disconnect if already connected wiht BTS.
    :param commissioning_timeout: Time in seconds to wait for BTS commissioning process finishes
    """

    if bts_type.lower() == "gnb":
        bts_commissioning = GnbCommissioning()
    elif bts_type.lower() == "enb":
        bts_commissioning = EnbCommissioning()
    else:
        raise NotSupportedBtsType("{} is not supported bts type. Please use ENB or GNB".format(bts_type))

    choosing_fun = _get_default_scf_for_du_from_yaml if custom_config else _get_default_scf_for_classical_bts
    scf_path = scf_path if scf_path else choosing_fun(bts_id=bts_id, bts_type=bts_type, prefix_tag=prefix_tag)[0]

    try:
        bts_commissioning.connect(bts_id=bts_id, du_id=0, interface='lmp', force=force_reconnect)
        connection_name = bts_commissioning.rest_alias.format(bts_id, 0)
        bts_commissioning.admin.validate_scf_online(scf_file=scf_path,
                                                    skip_parameter_relation_errors=False,
                                                    timeout=120,
                                                    detailed_output=True,
                                                    connection=connection_name)
    except AdminApiProcedureFailureException as e:
        logging.warning("Validation SCF Failed - Please consider adapt your SCF\n{}".format(repr(e)))

    bts_commissioning.perform_bts_full_commissioning(scf_file=scf_path,
                                                     bts_id=bts_id,
                                                     skip_parameter_relation_errors=True,
                                                     should_activate=True,
                                                     validate_scf=False,
                                                     timeout=commissioning_timeout,
                                                     du_id=0)

    GnbDuOperations().wait_unitl_connection_via_admin_is_possible(bts_id=bts_id, du_id=0)

    verify_if_another_sw_upload_is_needed(awaiting_time=awaiting_time, readiness_timeout=readiness_timeout,
                                          bts_id=bts_id, bts_type=bts_type, build_directory=build_directory,
                                          remove_build=remove_build, update_timeout=update_timeout)

    bts_commissioning.connect(bts_id=bts_id, du_id=0, interface='mplane', force=True)


def perform_full_commissioning_on_cloud_gnb(bts_id=0, cu_scf_path=None, du_scf_path=None, prefix_tag=None,
                                            awaiting_time=600, readiness_timeout=600, custom_config=False,
                                            build_directory="/tmp", remove_build=False, fix_errors=True, except_ongoing_operation=False,
                                            update_timeout=600):
    """
    Perform full commissioning on cloud gNB(CU and all DUs)
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param cu_scf_path: scf_path to CU - Common Unit - if not set then default will be selected
    :param du_scf_path: list of scf_path to all DUs -  if not set then default will be selected
    :param prefix_tag: scf_path to gNB - if scf_path not passed then default with specific tag will be selected
    :param awaiting_time: Time in seconds to wait for the Incompatible software alarm to occur
    :param readiness_timeout: Time in seconds to wait for BTS availability
    :param custom_config: Flag for enabling scf collection from custom-config directory
    :param build_directory: path to target directory where build will be downloaded in case of another sw upload need
    :param remove_build: Flag for enabling software package file removing
    :param fix_errors: define if validation errors should be fixed in commissioning file
    :param except_ongoing_operation: set to True if you want to except test failure due to ongoing operation
    :param update_timeout: Time in seconds to wait for BTS SW upload process finishes
    """
    perform_full_commissioning_on_all_dus(bts_id=bts_id, scf_path=du_scf_path, prefix_tag=prefix_tag,
                                          custom_config=custom_config, timeout=900)
    perform_full_commissioning_on_cu(bts_id=bts_id, scf_path=cu_scf_path, prefix_tag=prefix_tag,
                                     custom_config=custom_config, fix_errors=fix_errors,
                                     except_ongoing_operation=except_ongoing_operation)
    verify_if_another_sw_upload_is_needed(awaiting_time=awaiting_time, readiness_timeout=readiness_timeout,
                                          bts_id=bts_id, build_directory=build_directory, remove_build=remove_build,
                                          update_timeout=update_timeout)


def perform_commissioning_on_gnb_to_onair_state(bts_id=0, cu_scf_path=None, du_scf_path=None, prefix_tag=None,
                                                awaiting_time=600, readiness_timeout=600, custom_config=False,
                                                build_directory="/tmp", asir_hub=False, update_timeout=600,
                                                commissioning_timeout=400, delay_for_checking_on_air=30):
    """
    Perform full commissioning on Cloud or Classical gNB with CU error fix and same SW upload in case of
    'Incompatible SW version detected' alarm detection.
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param cu_scf_path: scf_path to CU - Common Unit - if not set then default will be selected
    :param du_scf_path: list of scf_path to all DUs -  if not set then default will be selected
    :param prefix_tag: scf_path to gNB - if scf_path not passed then default with specific tag will be selected
    :param awaiting_time: Time in seconds to wait for the Incompatible software alarm to occur
    :param readiness_timeout: Time in seconds to wait for BTS availability
    :param custom_config: Flag for enabling scf collection from custom-config directory
    :param build_directory: path to target directory where build will be downloaded in case of another sw upload need
    :param asir_hub: Flag for enabling ASIR hub commissioning
    :param update_timeout: Time in seconds to wait for BTS SW upload process finishes
    :param commissioning_timeout: Time in seconds to wait for BTS commissioning process finishes
    :param delay_for_checking_on_air: Time in seconds to start checking on air after commissioning
    """
    if _tl_config.is_testline_of_cloud_type(bts_id=bts_id):
        cu_path = cu_scf_path if cu_scf_path else _get_default_scf_for_cu(bts_id=bts_id, prefix_tag=prefix_tag)
        perform_full_commissioning_on_all_dus(bts_id=bts_id, scf_path=du_scf_path, prefix_tag=prefix_tag,
                                              custom_config=custom_config, timeout=900)
        CuCommissioning().perform_cu_commissioning(file_path=cu_path, fix_errors=True, except_ongoing_operation=False,
                                                   bts_id=bts_id)
        verify_if_another_sw_upload_is_needed(awaiting_time=awaiting_time, readiness_timeout=readiness_timeout,
                                              bts_id=bts_id, build_directory=build_directory,
                                              update_timeout=update_timeout)
    else:
        _wait_for_admin_api_connection(bts_id=bts_id)
        perform_full_commissioning_on_classical_gnb(bts_id=bts_id, scf_path=du_scf_path, prefix_tag=prefix_tag,
                                                    awaiting_time=awaiting_time, custom_config=False,
                                                    update_timeout=update_timeout,
                                                    commissioning_timeout=commissioning_timeout)
    if asir_hub:
        perform_full_commissioning_on_gnb_asir_hub(bts_id=bts_id, prefix_tag=prefix_tag)
    logging.debug("Sleep {} seconds before checking OnAir".format(delay_for_checking_on_air))
    time.sleep(delay_for_checking_on_air)
    wait_for_onair_on_all_dus(bts_id=bts_id, timeout=30 * 60)
    GnbBtslogCollector().setup_btslog_collector(bts_id=bts_id)


