def _perform_full_commissioning_on_asir_hub(bts_id=0, scf_path=None, prefix_tag=None, migrate_nidd=True,
                                            bts_type='GNB'):
    """
    Perform full commissioning on ASIR hub unit.
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param scf_path: scf_path to ASIR configuration - Common Unit - if not set then default will be selected
    :param prefix_tag: scf_path to ASIR - if scf_path not passed then default with specific prefix_tag will be selected
    :param migrate_nidd: flag which indicate if NIDD migration should be performed during commissioning process
    """
    asir_scf_path = scf_path if scf_path else _get_default_scf_for_asir_hub(bts_id, prefix_tag, bts_type)[0]
    asir_operations = GnbAsirHubOperations() if bts_type == 'GNB' else EnbAsirHubOperations()
    try:
        asir_operations.connect(bts_id=bts_id, force=True, timeout=240)
        asir_operations.perform_asir_commissioning(scf_path=asir_scf_path, migrate_nidd=migrate_nidd, bts_id=bts_id)
        asir_operations.disconnect(bts_id=bts_id)
    except AsirOperationFailed as e:
        # only one user with write permissions can be logged in to the ASIR at the same time
        asir_operations.disconnect(bts_id=bts_id)
        if "Validation failed" not in str(e) and "Invalid plan" not in str(e):
            raise e

        logging.warning(f"Validation SCF Failed: {repr(e)}")
        logging.debug("Performing commissioning via GUI")
        try:
            asir_operations.perform_asir_commissioning_via_gui(bts_id=bts_id, scf_path=asir_scf_path)
            msg = "ASIR commissioning via GUI was completed successfully. The adapted ASIR SCF should be located in \
            the root test results logs. Please use it and update it in the repository to avoid similar emails in \
            the future."
            send_email_with_default_template(
                subject='[Action Required] Update ASIR SCF in the repository',
                additional_info=msg,
                add_team_email=False
            )
            # only one user with write permissions can be logged in to the ASIR at the same time
            time.sleep(10)
        finally:
            asir_operations.logout_gui(bts_id=bts_id)


def perform_full_commissioning_on_asir_hub(bts_id=0, scf_path=None, prefix_tag=None, migrate_nidd=True):
    """ For keep Backward Compatibility"""
    logging.warning("'perform_full_commissioning_on_asir_hub' is deprecated - please use "
                    "'perform_full_commissioning_on_gnb_asir_hub'")
    perform_full_commissioning_on_gnb_asir_hub(bts_id, scf_path, prefix_tag, migrate_nidd)


def perform_full_commissioning_on_all_dus(bts_id=0, scf_path=None, prefix_tag=None, timeout=300, custom_config=False):
    """
    Perform full commissioning on all DUs under CU
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param scf_path: list of scf_path to all dus  - if not set then default will be selected
    :param prefix_tag: scf_path to gNB - if scf_path not passed then default with specific prefix_tag will be selected
    :param timeout: timeout for gNB commissioning
    :param custom_config: Flag for enabling scf collection from custom-config directory
    """

    choosing_fun = _get_default_scf_for_du_from_yaml if custom_config else _get_default_scf_for_dus
    scf_paths = scf_path if scf_path else choosing_fun(bts_id=bts_id, prefix_tag=prefix_tag)

    for du_id, scf_path in enumerate(scf_paths):
        GnbCommissioning().perform_bts_full_commissioning(scf_file=scf_path,
                                                          bts_id=bts_id,
                                                          skip_parameter_relation_errors=True,
                                                          should_activate=True,
                                                          validate_scf=False,
                                                          timeout=timeout,
                                                          du_id=du_id)


def upload_swconfig_on_classical_gnb(bts_id=0, sw_config_path=None, prefix_tag=None, reboot_after_upload=False):
    """
    Upload swconfig.txt file to gNB
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param sw_config_path: path to swconfig.txt to be uploaded  - if not set then default will be selected
    :param prefix_tag: prefix of swconfig.txt file - if sw_config_path not passed then default with specific
                                                     prefix_tag will be selected
    :param reboot_after_upload: flag to trigger gNB reboot or not after swconfig.txt upload
    """
    sw_config_path = sw_config_path if sw_config_path \
        else _get_default_swconfig_for_classical_gnb(bts_id=bts_id, prefix_tag=prefix_tag)
    GnbDuOperations().upload_swconfig(sw_config_path=sw_config_path, bts_id=bts_id, du_id=0,
                                      reboot_after_upload=reboot_after_upload)


def wait_for_onair_on_all_dus(bts_id=0, timeout=20 * 60):
    """
    Wait for all DUs be onAir
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :param timeout:  Time in seconds to wait for site to go onair
    """
    number_of_dus = _tl_config.get_count_of_distributed_units(bts_id=bts_id)
    for du_id in range(number_of_dus):
        GnbDuOperations().wait_for_site_to_be_onair(bts_id=bts_id, du_id=du_id, timeout=timeout)
        GnbCellOperations().wait_for_all_cells_to_be_onair(bts_id=bts_id, du_id=du_id, timeout=timeout)


def verify_if_another_sw_upload_is_needed(awaiting_time=600, readiness_timeout=600, bts_id=0, bts_type="GNB",
                                          build_directory="/tmp", remove_build=False, update_timeout=600):
    if bts_type == "GNB":
        bts_operations = GnbDuOperations()
        alarm = GnbAlarmVerification()
    elif bts_type == "ENB":
        bts_operations = EnbDuOperations()
        alarm = EnbAlarmVerification()
    else:
        raise NotSupportedBtsType("{} is not supported bts type. Please use ENB or GNB".format(bts_type))

    dus_number = _tl_config.get_count_of_distributed_units(bts_id=bts_id, bts_type=bts_type)

    readiness_counter = 0
    for du_id in range(dus_number):
        for i in range(5):
            try:
                if not alarm.verify_alarm_is_active(fault_name="No connection to unit", bts_id=bts_id, du_id=du_id):
                    bts_operations.reset_bts(bts_id=bts_id, du_id=du_id)
                    continue
            except AlarmIsNotActive:
                logging.info('RU detected. Checking if Incompatible SW version detected alarm is detected')

            if alarm.check_if_sw_incompatible_alarm_occurred(awaiting_time=awaiting_time,
                                                             bts_id=bts_id,
                                                             du_id=du_id):
                try:
                    _wait_for_bts_ready(bts_id=bts_id, du_id=du_id, bts_type=bts_type,
                                        readiness_timeout=readiness_timeout)
                    if bts_operations.is_sw_update_in_progress(bts_id=bts_id, du_id=du_id):
                        bts_operations.wait_till_sw_update_is_possible(bts_id=bts_id, du_id=du_id)
                    else:
                        _attempt_sw_upload(bts_id=bts_id, du_id=du_id, bts_type=bts_type, target_path=build_directory,
                                           remove_build=remove_build, update_timeout=update_timeout)
                    alarm.wait_for_alarm_deactivation(fault_id=23, awaiting_time=300, bts_id=bts_id, du_id=du_id)
                except BtsNotReady:
                    logging.warning('The BTS is not ready for update yet.')
                    readiness_counter += 1
                    continue
                except SwUpgradeException:
                    logging.warning('The SW upload failed.')
                    awaiting_time = 300
                    continue
                except Release21AException:
                    logging.debug('This block should only be triggered in the release 21A or lower')
                    time.sleep(300)
                    _attempt_sw_upload(bts_id=bts_id, du_id=du_id, bts_type=bts_type, target_path=build_directory,
                                       remove_build=remove_build)
                    break
            else:
                break
        else:
            if readiness_counter == 5:
                logging.error('The BTS is still busy after {} minutes'.format((5 * readiness_timeout) / 60))
            raise WrongApiException("Software could not have been uploaded")


def _get_default_scf_for_dus(bts_id=0, prefix_tag=None):
    dfl = DefaultFileLocation()
    number_of_dus = _tl_config.get_count_of_distributed_units(bts_id=bts_id)
    commission_dir = dfl.get_commissioning_dir()
    scf_names = [dfl.get_default_scf_name('GNB', bts_id, prefix_tag, sub_device="DU{}".format(du_id))
                 for du_id in range(number_of_dus)]
    scf_dus = [os.path.join(commission_dir, scf_name) for scf_name in scf_names]

    return scf_dus


def _get_default_scf_for_cu(bts_id=0, prefix_tag=None):
    dfl = DefaultFileLocation()
    commission_dir = dfl.get_commissioning_dir()
    scf_name = dfl.get_default_scf_name('GNB', bts_id, prefix_tag, sub_device='CU')
