def _wait_for_admin_api_connection(bts_id=0):
    admin_api_connection_attempts = 0
    while admin_api_connection_attempts < 10:
        try:
            GnbAlarmVerification().check_if_sw_incompatible_alarm_occurred(bts_id=bts_id)
            break
        except (AdminApiConnectionClosedException, AdminApiProcedureFailureException):
            admin_api_connection_attempts = admin_api_connection_attempts + 1
        time.sleep(30)
    else:
        scf_path = _get_default_scf_for_classical_bts()
        GnbCommissioning().perform_bts_full_commissioning_via_gui(scf_path[0])


def _get_default_scf_for_from_yaml(gnb_part):
    yaml_path = DefaultFileLocation().get_custom_config_yaml_path()
    hws = []
    with open(yaml_path) as yf:
        content = yaml.load(yf, Loader=yaml.FullLoader)
        for item in content['nodes']:
            if isinstance(item, dict):
                for f in item['files']:
                    if f['hw_type'] == gnb_part and f['file_type'] == 'scfc':
                        hws.append(f)
    hws.sort(key=lambda x: x['hw_id'])
    scf_paths = [os.path.join(get_repository_path(), 'custom-config', hw['file_path']) for hw in hws]
    return scf_paths


def _get_default_scf_for_cu_from_yaml(**kwargs):
    return _get_default_scf_for_from_yaml(gnb_part='cu')


def _get_default_scf_for_du_from_yaml(**kwargs):
    return _get_default_scf_for_from_yaml(gnb_part='du')


def _wait_for_bts_ready(bts_id=0, du_id=0, bts_type="GNB", readiness_timeout=600):
    bts_types = {"GNB": GnbDuOperations(),
                 "ENB": EnbDuOperations()}

    try:
        bts = bts_types[bts_type]
    except KeyError:
        raise NotSupportedBtsType("{} is not supported bts type. Please use ENB or GNB".format(bts_type))

    alias = device_aliases.rest_bts_du.format(bts_type, bts_id, du_id)

    bts_alarm = GnbAlarmVerification()
    try:
        bts.connect(bts_id=bts_id, du_id=du_id, interface='lmp')
        bts.admin.wait_sw_update_possible(readiness_timeout=readiness_timeout,
                                          timeout=(readiness_timeout + 100),
                                          connection=alias)
        bts_alarm.verify_alarm_is_active(fault_name='GPS receiver alarm: firmware upgrade ongoing', bts_id=bts_id,
                                         du_id=du_id)
        logging.debug('GPS firmware upgrade ongoing - wait for finish')
        bts_alarm.wait_for_alarm_deactivation(fault_id=4420, awaiting_time=1800, bts_id=bts_id, du_id=du_id)
        logging.debug('GPS firmware upgrade finish')
        # check again if sw_update_possible
        bts.admin.wait_sw_update_possible(readiness_timeout=readiness_timeout,
                                          timeout=(readiness_timeout + 100),
                                          connection=alias)
        # sleep for BTS availability after GPS firmware upgrade
        time.sleep(90)
    except (AdminApiConnectionClosedException, AdminApiProcedureFailureException) as ex:
        error_code = "errorcode: 2"
        if error_code in str(ex).lower():
            raise Release21AException
        else:
            raise BtsNotReady
    except AlarmIsNotActive:
        logging.debug('GPS firmware upgrade alarm is not active, continue')
    finally:
        bts.disconnect(bts_id=bts_id, du_id=du_id)


def _attempt_sw_upload(bts_id=0, du_id=0, bts_type="GNB", target_path="/tmp", remove_build=False, update_timeout=600):
    if bts_type == "GNB":
        bts_operations = GnbDuOperations()
        bts_sw_update = GnbSwUpdate()
    elif bts_type == "ENB":
        bts_operations = EnbDuOperations()
        bts_sw_update = EnbSwUpdate()
    else:
        raise NotSupportedBtsType("{} is not supported bts type. Please use ENB or GNB".format(bts_type))

    try:
        sw_path = _check_ute_ca_cache(bts_operations.get_bts_sw_version(bts_id=bts_id, du_id=du_id))
        if sw_path is None:
            bts_sw_version = bts_operations.get_bts_sw_version(bts_id=bts_id, du_id=du_id)
            sw_path = bts_sw_update.download_sw_package(bts_sw_version, target_path)
        bts_sw_update.update_software(sw_package_dir=sw_path, timeout=update_timeout, bts_id=bts_id, du_id=du_id)
        logging.info('Software package {} uploaded'.format(sw_path.split('/')[-1]))
        if remove_build:
            os.remove(sw_path)
            logging.info('Software package {} removed'.format(sw_path))
    except (AdminApiConnectionClosedException, AdminApiProcedureFailureException):
        raise SwUpgradeException


def _check_ute_ca_cache(bts_sw_version):
    ute_ca_cache_dir = "/home/ute/.ute-ca/cache/bts/"
    sw_version = SwVersionFactory.create_sw_version(bts_sw_version)
    if isinstance(sw_version, SbtsSwVersion):
        target_dir = os.path.join(ute_ca_cache_dir, sw_version.raw_with_release)
        package_name = sw_version.get_package()
    else:
        target_dir = os.path.join(ute_ca_cache_dir, sw_version.simplified)
        package_name = sw_version.get_package()
    logging.debug(f"Checking {package_name} in {target_dir}")
    try:
        if package_name in os.listdir(target_dir):
            logging.info('Software package {} already in {}'.format(package_name, target_dir))
            return os.path.join(target_dir, package_name)
    except OSError:
        return None
